using System;
using Framework.AI.Actions;
using Framework.AI.Core;
using Framework.Movement;
using Framework.Parameters;
using Game.AI.Actions;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.Map;
using Game.Stage;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// 敵AIの行動実行システムを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class MazeEnemyActionTest
        : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("テスト用ステージ管理Prefab。")]
        private MazeStageManager stageManagerPrefab;

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定テスト件数。
        /// </summary>
        private const int ExpectedTestCount = 40;

        /// <summary>
        /// 敵の初期座標。
        /// </summary>
        private static readonly Vector2Int StartPosition =
            new Vector2Int(1, 1);

        /// <summary>
        /// テスト用ステージ。
        /// </summary>
        private MazeStageManager stageManager;

        /// <summary>
        /// テスト用移動オブジェクト。
        /// </summary>
        private GameObject movementObject;

        /// <summary>
        /// テスト用移動コントローラー。
        /// </summary>
        private GridMovementController movement;

        /// <summary>
        /// テスト用パラメーターセット。
        /// </summary>
        private ParameterSet<MazeEnemyParameter> parameters;

        /// <summary>
        /// テスト用敵AIコンテキスト。
        /// </summary>
        private MazeEnemyContext enemy;

        /// <summary>
        /// テスト用行動コンテキスト。
        /// </summary>
        private MazeEnemyActionContext context;

        /// <summary>
        /// テスト用行動管理システム。
        /// </summary>
        private AgentActionController<
            MazeEnemyActionType,
            MazeEnemyActionContext> controller;

        /// <summary>
        /// 開始時にテストを実行する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "Play Modeで実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                Prepare();
                TestInitialization();

                Prepare();
                TestMoveSpeed();

                Prepare();
                TestMovement();

                Prepare();
                TestDestinationChange();

                Prepare();
                TestActionSwitch();

                Prepare();
                TestFailure();

                Prepare();
                TestLifecycle();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                Cleanup();
            }

            Debug.Log(
                $"【MazeEnemyAction テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// テスト環境を生成する。
        /// </summary>
        private void Prepare()
        {
            Cleanup();

            if (stageManagerPrefab == null)
            {
                throw new InvalidOperationException(
                    "テスト用ステージPrefabが未設定です。");
            }

            stageManager = Instantiate(stageManagerPrefab);

            if (!stageManager.GenerateStage())
            {
                throw new InvalidOperationException(
                    "ステージ生成に失敗しました。");
            }

            if (stageManager.Map.Width < 7 ||
                stageManager.Map.Height < 7)
            {
                throw new InvalidOperationException(
                    "7×7以上のマップが必要です。");
            }

            // 固定条件でテストするため全セルを床にする。
            stageManager.Map.Fill(MazeCell.CreateFloor());

            // ステージの即時クリアを防止する。
            stageManager.Map.SetCell(
                Vector2Int.zero,
                MazeCell.CreateFloor(MazeCellFlags.Gem));

            movementObject =
                new GameObject("ActionTest_Movement");

            movement = movementObject
                .AddComponent<GridMovementController>();

            movement.AutoUpdate = false;

            movement.Initialize(
                stageManager.CoordinateConverter,
                stageManager.IsWalkable,
                StartPosition);

            parameters =
                MazeEnemyParameterCatalog.CreateParameterSet();

            parameters.SetBaseValue(
                MazeEnemyParameter.MoveSpeed, 2f);

            parameters.SetBaseValue(
                MazeEnemyParameter.ChaseSpeedMultiplier, 1.5f);

            parameters.SetBaseValue(
                MazeEnemyParameter.EscapeSpeedMultiplier, 2f);

            var agentContext =
                new AgentContext<MazeEnemyParameter>(
                    "ActionTest",
                    parameters);

            enemy = new MazeEnemyContext(
                agentContext,
                stageManager,
                movement,
                StartPosition);

            context =
                new MazeEnemyActionContext(enemy);

            controller =
                new AgentActionController<
                    MazeEnemyActionType,
                    MazeEnemyActionContext>();

            controller.TryRegister(
                new MazeEnemyIdleAction());

            RegisterMoveAction(MazeEnemyActionType.Patrol);
            RegisterMoveAction(MazeEnemyActionType.Explore);
            RegisterMoveAction(MazeEnemyActionType.Chase);
            RegisterMoveAction(MazeEnemyActionType.Intercept);
            RegisterMoveAction(MazeEnemyActionType.Escape);
            RegisterMoveAction(
                MazeEnemyActionType.ReturnToTerritory);

            if (!stageManager.StartStage())
            {
                throw new InvalidOperationException(
                    "ステージ開始に失敗しました。");
            }
        }

        /// <summary>
        /// 移動行動を登録する。
        /// </summary>
        /// <param name="action">行動の種類</param>
        private void RegisterMoveAction(
            MazeEnemyActionType action)
        {
            controller.TryRegister(
                new MazeEnemyMoveAction(action));
        }

        /// <summary>
        /// 目的地を設定して移動行動を開始する。
        /// </summary>
        /// <param name="action">行動の種類</param>
        /// <param name="destination">目的地</param>
        /// <returns>開始できた場合はtrue</returns>
        private bool StartMove(
            MazeEnemyActionType action,
            Vector2Int destination)
        {
            return context.TrySetDestination(
                       action, destination) &&
                   controller.TryStartAction(
                       action, context);
        }

        /// <summary>
        /// 指定された行動を実行中であるか確認する。
        /// </summary>
        /// <param name="action">行動の種類</param>
        /// <returns>実行中の場合はtrue</returns>
        private bool IsCurrentAction(
            MazeEnemyActionType action)
        {
            return controller.TryGetCurrentActionId(
                       out MazeEnemyActionType current) &&
                   current == action;
        }

        /// <summary>
        /// 初期化と目的地管理を検証する。
        /// </summary>
        private void TestInitialization()
        {
            bool initial =
                context.IsValid &&
                context.CanAct &&
                !context.IsDisposed;

            Debug.Assert(initial, "初期状態", this);
            Check(initial, "初期状態");

            bool dependencies =
                ReferenceEquals(context.Enemy, enemy) &&
                ReferenceEquals(context.Movement, movement);

            Debug.Assert(dependencies, "依存関係", this);
            Check(dependencies, "依存関係");

            bool registered = controller.Count == 7;

            Debug.Assert(registered, "7種類の行動登録", this);
            Check(registered, "7種類の行動登録");

            Vector2Int destination =
                new Vector2Int(4, 1);

            bool set = context.TrySetDestination(
                MazeEnemyActionType.Patrol,
                destination);

            Debug.Assert(set, "目的地設定", this);
            Check(set, "目的地設定");

            bool get = context.TryGetDestination(
                MazeEnemyActionType.Patrol,
                out Vector2Int result) &&
                result == destination;

            Debug.Assert(get, "目的地取得", this);
            Check(get, "目的地取得");

            bool idleRejected =
                !context.TrySetDestination(
                    MazeEnemyActionType.Idle,
                    destination);

            Debug.Assert(idleRejected, "待機目的地の拒否", this);
            Check(idleRejected, "待機目的地の拒否");

            bool outsideRejected =
                !context.TrySetDestination(
                    MazeEnemyActionType.Chase,
                    new Vector2Int(-1, -1));

            Debug.Assert(outsideRejected, "範囲外目的地の拒否", this);
            Check(outsideRejected, "範囲外目的地の拒否");

            bool removed =
                context.RemoveDestination(
                    MazeEnemyActionType.Patrol) &&
                context.DestinationCount == 0;

            Debug.Assert(removed, "目的地削除", this);
            Check(removed, "目的地削除");
        }

        /// <summary>
        /// 行動ごとの移動速度を検証する。
        /// </summary>
        private void TestMoveSpeed()
        {
            bool patrol = Mathf.Approximately(
                context.GetMoveSpeed(
                    MazeEnemyActionType.Patrol), 2f);

            Debug.Assert(patrol, "巡回速度", this);
            Check(patrol, "巡回速度");

            bool explore = Mathf.Approximately(
                context.GetMoveSpeed(
                    MazeEnemyActionType.Explore), 2f);

            Debug.Assert(explore, "探索速度", this);
            Check(explore, "探索速度");

            bool chase = Mathf.Approximately(
                context.GetMoveSpeed(
                    MazeEnemyActionType.Chase), 3f);

            Debug.Assert(chase, "追跡速度", this);
            Check(chase, "追跡速度");

            bool intercept = Mathf.Approximately(
                context.GetMoveSpeed(
                    MazeEnemyActionType.Intercept), 3f);

            Debug.Assert(intercept, "迎撃速度", this);
            Check(intercept, "迎撃速度");

            bool escape = Mathf.Approximately(
                context.GetMoveSpeed(
                    MazeEnemyActionType.Escape), 4f);

            Debug.Assert(escape, "逃走速度", this);
            Check(escape, "逃走速度");

            bool returnSpeed = Mathf.Approximately(
                context.GetMoveSpeed(
                    MazeEnemyActionType.ReturnToTerritory), 2f);

            Debug.Assert(returnSpeed, "帰還速度", this);
            Check(returnSpeed, "帰還速度");
        }

        /// <summary>
        /// 基本移動と訪問記憶を検証する。
        /// </summary>
        private void TestMovement()
        {
            Vector2Int destination =
                new Vector2Int(3, 1);

            bool started = StartMove(
                MazeEnemyActionType.Patrol,
                destination);

            Debug.Assert(started, "巡回行動開始", this);
            Check(started, "巡回行動開始");

            bool following =
                context.PathFollower.IsFollowing &&
                context.PathFollower.Destination ==
                    destination;

            Debug.Assert(following, "経路追従開始", this);
            Check(following, "経路追従開始");

            movement.Tick(0.5f);

            bool firstCell =
                movement.CurrentCell ==
                    new Vector2Int(2, 1);

            Debug.Assert(firstCell, "最初のセル到達", this);
            Check(firstCell, "最初のセル到達");

            bool visited =
                enemy.SpatialMemory.HasVisited(
                    new Vector2Int(2, 1));

            Debug.Assert(visited, "訪問記憶の自動更新", this);
            Check(visited, "訪問記憶の自動更新");

            movement.Tick(0.5f);

            bool arrived =
                movement.CurrentCell == destination &&
                context.PathFollower.State ==
                    GridPathFollowerState.Completed;

            Debug.Assert(arrived, "目的地到達", this);
            Check(arrived, "目的地到達");

            controller.Tick(context, 0.2f);

            bool completed =
                !controller.HasCurrentAction &&
                !movement.IsMoving;

            Debug.Assert(completed, "行動の正常終了", this);
            Check(completed, "行動の正常終了");
        }

        /// <summary>
        /// 移動中の目的地変更を検証する。
        /// </summary>
        private void TestDestinationChange()
        {
            bool started = StartMove(
                MazeEnemyActionType.Chase,
                new Vector2Int(5, 1));

            Debug.Assert(started, "追跡行動開始", this);
            Check(started, "追跡行動開始");

            movement.Tick(0.1f);

            bool traversing = movement.IsTraversing;

            Debug.Assert(traversing, "セル間移動", this);
            Check(traversing, "セル間移動");

            Vector2Int newDestination =
                new Vector2Int(2, 4);

            context.TrySetDestination(
                MazeEnemyActionType.Chase,
                newDestination);

            controller.Tick(context, 0.2f);

            bool updated =
                context.PathFollower.Destination ==
                    newDestination &&
                IsCurrentAction(MazeEnemyActionType.Chase);

            Debug.Assert(updated, "追跡目的地の更新", this);
            Check(updated, "追跡目的地の更新");

            bool origin =
                context.PathFollower.Path.Count > 0 &&
                context.PathFollower.Path[0] ==
                    new Vector2Int(2, 1);

            Debug.Assert(origin, "移動中の経路起点", this);
            Check(origin, "移動中の経路起点");

            movement.Tick(3f);
            controller.Tick(context, 0.2f);

            bool arrived =
                movement.CurrentCell == newDestination &&
                !controller.HasCurrentAction;

            Debug.Assert(arrived, "変更後の目的地到達", this);
            Check(arrived, "変更後の目的地到達");
        }

        /// <summary>
        /// 行動の切り替えと待機を検証する。
        /// </summary>
        private void TestActionSwitch()
        {
            bool patrol = StartMove(
                MazeEnemyActionType.Patrol,
                new Vector2Int(5, 1));

            Debug.Assert(patrol, "切り替え前の巡回", this);
            Check(patrol, "切り替え前の巡回");

            movement.Tick(0.25f);

            bool chase = StartMove(
                MazeEnemyActionType.Chase,
                new Vector2Int(2, 4));

            Debug.Assert(chase, "巡回から追跡へ切り替え", this);
            Check(chase, "巡回から追跡へ切り替え");

            bool speed =
                IsCurrentAction(MazeEnemyActionType.Chase) &&
                Mathf.Approximately(
                    movement.MoveSpeed, 3f);

            Debug.Assert(speed, "切り替え後の速度反映", this);
            Check(speed, "切り替え後の速度反映");

            bool idle =
                controller.TryStartAction(
                    MazeEnemyActionType.Idle,
                    context) &&
                IsCurrentAction(MazeEnemyActionType.Idle);

            Debug.Assert(idle, "待機行動への切り替え", this);
            Check(idle, "待機行動への切り替え");

            movement.Tick(2f);
            controller.Tick(context, 0.2f);

            bool stopped =
                !movement.IsMoving &&
                movement.IsAtCellCenter &&
                movement.CurrentCell ==
                    new Vector2Int(2, 1) &&
                IsCurrentAction(MazeEnemyActionType.Idle);

            Debug.Assert(stopped, "セル中心での待機", this);
            Check(stopped, "セル中心での待機");
        }

        /// <summary>
        /// 異常系と経路失敗を検証する。
        /// </summary>
        private void TestFailure()
        {
            bool noDestination =
                !controller.TryStartAction(
                    MazeEnemyActionType.Chase,
                    context);

            Debug.Assert(noDestination, "目的地未設定の拒否", this);
            Check(noDestination, "目的地未設定の拒否");

            stageManager.Map.SetCell(
                new Vector2Int(4, 4),
                MazeCell.CreateWall());

            bool wall =
                !context.TrySetDestination(
                    MazeEnemyActionType.Chase,
                    new Vector2Int(4, 4));

            Debug.Assert(wall, "壁への目的地設定拒否", this);
            Check(wall, "壁への目的地設定拒否");

            parameters.SetBaseValue(
                MazeEnemyParameter.MoveSpeed, 0f);

            bool zeroSpeed =
                !StartMove(
                    MazeEnemyActionType.Patrol,
                    new Vector2Int(4, 1));

            Debug.Assert(zeroSpeed, "速度0の行動拒否", this);
            Check(zeroSpeed, "速度0の行動拒否");

            parameters.SetBaseValue(
                MazeEnemyParameter.MoveSpeed, 2f);

            bool started = StartMove(
                MazeEnemyActionType.Patrol,
                new Vector2Int(4, 1));

            Debug.Assert(started, "経路失敗検証用の移動開始", this);
            Check(started, "経路失敗検証用の移動開始");

            stageManager.Map.SetCell(
                new Vector2Int(3, 1),
                MazeCell.CreateWall());

            movement.Tick(0.5f);

            bool failed =
                context.PathFollower.State ==
                    GridPathFollowerState.Failed &&
                context.PathFollower.LastFailureReason ==
                    GridPathFailureReason.CellBlocked;

            Debug.Assert(failed, "経路上の壁による失敗", this);
            Check(failed, "経路上の壁による失敗");

            AgentActionExitReason exitReason =
                AgentActionExitReason.Succeeded;

            controller.ActionEnded +=
                (action, reason) => exitReason = reason;

            controller.Tick(context, 0.2f);

            bool ended =
                !controller.HasCurrentAction &&
                exitReason == AgentActionExitReason.Failed &&
                !movement.IsMoving;

            Debug.Assert(ended, "失敗した行動の終了", this);
            Check(ended, "失敗した行動の終了");
        }

        /// <summary>
        /// 破棄処理と外部所有権を検証する。
        /// </summary>
        private void TestLifecycle()
        {
            context.TrySetDestination(
                MazeEnemyActionType.Patrol,
                new Vector2Int(3, 1));

            context.TrySetDestination(
                MazeEnemyActionType.Chase,
                new Vector2Int(5, 1));

            context.ClearDestinations();

            bool cleared =
                context.DestinationCount == 0;

            Debug.Assert(cleared, "全目的地の削除", this);
            Check(cleared, "全目的地の削除");

            context.Dispose();
            context.Dispose();

            bool disposed =
                context.IsDisposed &&
                !context.IsValid &&
                context.PathFollower.IsDisposed;

            Debug.Assert(disposed, "行動コンテキストの破棄", this);
            Check(disposed, "行動コンテキストの破棄");

            bool rejected =
                !context.TrySetDestination(
                    MazeEnemyActionType.Patrol,
                    new Vector2Int(3, 1)) &&
                !context.TryMoveTo(
                    new Vector2Int(3, 1));

            Debug.Assert(rejected, "破棄後の操作拒否", this);
            Check(rejected, "破棄後の操作拒否");

            bool ownership =
                enemy.IsValid &&
                !parameters.IsDisposed &&
                movement.IsInitialized;

            Debug.Assert(ownership, "外部所有権の維持", this);
            Check(ownership, "外部所有権の維持");
        }

        /// <summary>
        /// テスト環境を解放する。
        /// </summary>
        private void Cleanup()
        {
            if (controller != null && context != null)
            {
                controller.Stop(context);
            }

            controller = null;

            context?.Dispose();
            context = null;

            enemy?.Dispose();
            enemy = null;

            parameters?.Dispose();
            parameters = null;

            if (movementObject != null)
            {
                movementObject.SetActive(false);
                Destroy(movementObject);

                movementObject = null;
            }

            movement = null;

            if (stageManager != null)
            {
                stageManager.gameObject.SetActive(false);
                Destroy(stageManager.gameObject);

                stageManager = null;
            }
        }

        /// <summary>
        /// オブジェクト破棄時に資源を解放する。
        /// </summary>
        private void OnDestroy()
        {
            Cleanup();
        }

        /// <summary>
        /// 個別テスト結果を出力する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
